      "json": "[{\"target_reduction\": \"50% reduction\", \"target_reduction_scope\": \"Scope 1 and 2 emissions\", \"classification_of_target\": \"Absolute reduction, Science-Based Target (SBTi)\", \"target_year\": \"2032\", \"baseline_year\": \"2021\", \"baseline_value\": null}, {\"target_reduction\": \"over 60% reduction\", \"target_reduction_scope\": \"Scope 3 emissions\", \"classification_of_target\": \"Absolute reduction, Science-Based Target (SBTi)\", \"target_year\": \"2032\", \"baseline_year\": \"2021\", \"baseline_value\": null}]",
